function calendar(){let a=[...state.events].sort((x,y)=>(x.date||"9999").localeCompare(y.date||"9999"));return heading("برنامه‌ریزی","زمان‌بندی","مهلت‌های تولید و نقاط عطف کسب‌وکار را پیگیری کنید.",btn("+ افزودن event","add-events"))+(a.length?'<div class="calendar-list">'+a.map(x=>'<div class="calendar-day"><div class="calendar-date">'+esc(date(x.date))+'</div><div class="calendar-events"><div class="calendar-event"><strong>'+esc(x.title)+'</strong><small>'+esc(x.kind||"Task")+' · '+esc(x.description||"")+'</small><div class="meta-row">'+pill(x.status||"Planned")+' <button class="button small secondary" data-action="edit" data-type="events" data-id="'+x.id+'">ویرایش</button><button class="button small danger" data-action="delete" data-type="events" data-id="'+x.id+'">حذف</button></div></div></div></div>').join("")+'</div>':emptyBox("هنوز چیزی زمان‌بندی نشده است","یک مهلت یا نقطه عطف محتوایی اضافه کنید.","add-events","افزودن رویداد"))}
function aiStudio(){return heading("کارگاه هوش مصنوعی","استودیو هوش مصنوعی","ایده‌ات را وارد کن؛ پیش‌نویس هوشمند بساز و قبل از انتشار، نتیجه را بررسی کن.","")+'<section class="panel ai-setup"><div class="ai-hero"><div class="ai-orb">✦</div><div><span class="eyebrow">AI فضای کاری</span><h2>ایده را به خروجی تبدیل کن</h2><p class="muted">اتصال امن به درگاه اختصاصی شما؛ کلید سرویس هوش مصنوعی فقط در تنظیمات Worker نگهداری می‌شود.</p></div></div><form id="ai-form" class="form-fields"><div class="field"><label for="ai-endpoint">🔗 نشانی درگاه هوش مصنوعی</label><input id="ai-endpoint" name="endpoint" type="url" dir="ltr" value="'+esc(aiEndpoint||"https://ai-business-core.mohammadfadaiemacbook.workers.dev/api/generate")+'" placeholder="https://your-worker.workers.dev/api/generate" required></div><div class="field"><label for="ai-token">🔐 توکن دسترسی برنامه</label><input id="ai-token" name="token" type="password" dir="ltr" autocomplete="off" minlength="24" value="'+esc(aiToken)+'" placeholder="توکن دسترسی را وارد کنید" required><small>توکن فقط تا پایان همین نشست در حافظه فرم می‌ماند و در حافظه مرورگر ذخیره نمی‌شود.</small></div><div class="ai-fields-grid"><div class="field"><label for="ai-task">⚡ نوع خروجی</label><select id="ai-task" name="task"><option value="trend_strategy">🔥 تحلیل ترند و ایده‌های تازه</option><option value="youtube_research">🔎 طرح پژوهش یوتیوب</option><option value="video_outline">🧩 ساختار ویدئو</option><option value="video_script">✍️ نگارش سناریوی ویدئو</option><option value="title_ideas">💡 ایده عنوان و کاور</option><option value="youtube_metadata">🧾 عنوان، توضیحات و تگ یوتیوب</option><option value="instagram_repurpose">📱 بازآفرینی برای اینستاگرام</option><option value="social_caption">✍️ کپشن و متن شبکه‌های اجتماعی</option><option value="thumbnail_brief">🖼️ ایده تامبنیل حرفه‌ای</option><option value="comment_reply">💬 پاسخ به کامنت مخاطب</option></select></div><div class="field"><label for="ai-topic">🎯 موضوع یا عنوان اصلی</label><input id="ai-topic" name="topic" maxlength="300" required placeholder="مثلاً: ابزارهای رایگان هوش مصنوعی برای کسب‌وکارها"></div></div><div class="field"><label for="ai-audience">👥 مخاطب هدف</label><input id="ai-audience" name="audience" maxlength="300" placeholder="مثلاً: صاحبان کسب‌وکارهای کوچک"></div><div class="field"><label for="ai-context">📝 توضیحات، نکته‌ها و منابع</label><textarea id="ai-context" name="context" rows="5" maxlength="12000" placeholder="اطلاعات و منابع معتبر را اینجا وارد کنید. داده خصوصی وارد نکنید."></textarea></div><div class="actions ai-submit-row"><button class="button primary ai-generate-button" type="submit" id="ai-generate" '+(aiBusy?'disabled':'')+'>'+(aiBusy?'در حال تولید…':'✦ تولید پیش‌نویس')+'</button><span class="muted">خروجی هوش مصنوعی نیازمند بازبینی انسانی است.</span></div></form></section><section class="panel section-gap"><div class="panel-head"><div><h2>🔐 اتصال مدل دوم و سرویس‌های رسانه</h2><p>کلیدها فقط از طریق ارتباط امن ارسال و در Worker با AES-GCM رمزگذاری می‌شوند؛ در حافظه مرورگر ذخیره نمی‌شوند.</p></div></div><form id="provider-form" class="form-fields"><div class="field"><label>نشانی API مدل دوم (سازگار با OpenAI)</label><input name="secondaryUrl" type="url" dir="ltr" placeholder="https://openrouter.ai/api/v1/chat/completions"></div><div class="field"><label>کلید API مدل دوم</label><input name="secondaryKey" type="password" autocomplete="off" placeholder="کلید مدل دوم"></div><div class="field"><label>شناسه مدل دوم</label><input name="secondaryModel" dir="ltr" placeholder="provider/model-name"></div><div class="divider"></div><div class="field"><label>کلید API رسمی Anthropic برای اتصال Claude</label><input name="claudeKey" type="password" autocomplete="off" placeholder="sk-ant-..."></div><div class="field"><label>شناسه مدل Claude</label><input name="claudeModel" dir="ltr" placeholder="مدل فعال حساب Anthropic"></div><p class="muted">Claude از طریق Messages API به‌عنوان بازبین مستقل متصل می‌شود. API آنتروپیک جدا از اشتراک چت Claude صورتحساب دارد.</p><div class="divider"></div><div class="field"><label>کلید ElevenLabs برای گویندگی</label><input name="elevenlabsKey" type="password" autocomplete="off" placeholder="ElevenLabs API key"></div><div class="field"><label>شناسه صدای فارسی (اختیاری)</label><input name="elevenlabsVoiceId" dir="ltr" placeholder="Persian Voice ID"></div><div class="field"><label>شناسه صدای انگلیسی Nexora AI</label><input name="elevenlabsEnglishVoiceId" dir="ltr" placeholder="English Voice ID"></div><p class="muted">برای محتوای Nexora AI صدای انگلیسی جداگانه انتخاب کن. شناسه صدا را از Voice Library در ElevenLabs بردار.</p><div class="field"><label>مدل گویندگی</label><input name="elevenlabsModel" dir="ltr" value="eleven_multilingual_v2"></div><div class="divider"></div><div class="field"><label>نشانی API تولید تصویر (سازگار با OpenAI Images)</label><input name="imageUrl" type="url" dir="ltr" value="https://api.openai.com/v1/images/generations"></div><div class="field"><label>کلید API تولید تصویر</label><input name="imageKey" type="password" autocomplete="off" placeholder="Image API key"></div><div class="field"><label>مدل تصویر</label><input name="imageModel" dir="ltr" value="gpt-image-1"></div><div class="actions"><button class="button primary" type="submit">ذخیره امن اتصال‌ها</button><button class="button secondary" type="button" data-action="media-check">بررسی وضعیت اتصال‌ها</button></div><p class="muted">برای فعال‌شدن این امکانات باید کلیدهای معتبر از سرویس‌دهندگان مربوط داشته باشی. کلید اصلی تولید متن از تنظیمات فعلی Worker استفاده می‌کند.</p></form><div id="media-capabilities" class="muted"></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>📄 پیش‌نویس تولیدشده</h2><p>ادعاها و اطلاعات را پیش از استفاده با منابع معتبر تطبیق دهید.</p></div><div class="actions"><button class="button secondary" data-action="ai-copy" '+(!aiOutput?'disabled':'')+'>کپی متن</button><button class="button secondary" data-action="ai-save" '+(!aiOutput?'disabled':'')+'>ذخیره در استودیو محتوا</button></div></div><pre class="ai-output">'+(aiOutput?esc(aiOutput):'هنوز محتوایی تولید نشده است؛ موضوع را وارد کنید و روی «تولید پیش‌نویس» بزنید.')+(aiReview?'<hr><strong>بازبینی مستقل</strong><p>'+esc(aiReview)+'</p>':'')+'</pre></section><section class="panel section-gap"><div class="panel-head"><div><h2>🔥 رادار ترند و سازنده ویدئو</h2><p>موضوع‌های تازه را از ویدئوهای اخیر یوتیوب پیدا کن و ایده‌های جدید بساز.</p></div></div><input id="trend-query" type="hidden" value="artificial intelligence agents, AI tools, robotics, future technology and automation"><div class="field"><label>کانال فعال</label><p class="muted">Nexora AI · حوزه ثابت: AI agents، ابزارهای هوش مصنوعی، رباتیک، اتوماسیون و فناوری آینده · مخاطب انگلیسی‌زبان جهانی · بازار تحقیق: آمریکا و روندهای جهانی</p></div><div class="actions"><button class="button primary" data-action="trend-discover">کشف ترندهای Nexora AI</button><button class="button primary" data-action="video-auto">🚀 پیدا کن، تحلیل کن و ویدئو را خودکار بساز</button><button class="button secondary" data-action="video-titles">تولید چند عنوان جذاب</button><button class="button secondary" data-action="video-thumbnail-ideas">ایده تامبنیل و متن روی کاور</button><button class="button secondary" data-action="video-caption">نوشتن کپشن شبکه‌های اجتماعی</button><button class="button secondary" data-action="video-image">ساخت تصویر اختصاصی ویدئو</button></div><div class="actions"><button class="button secondary" data-action="media-check">بررسی سرویس‌های رسانه و مدل دوم</button></div><div id="media-capabilities" class="muted"></div><div id="trend-results" class="section-gap"></div><div class="actions"><button class="button secondary" data-action="video-script">۱. تولید سناریوی کامل</button><button class="button secondary" data-action="video-metadata">۲. تولید اطلاعات یوتیوب</button><button class="button primary" data-action="video-build">۳. ساخت ویدئو</button><button class="button secondary" data-action="video-send">آماده‌سازی آپلود خصوصی</button><button class="button secondary" data-action="video-subtitles">دریافت زیرنویس SRT</button><button class="button secondary" data-action="video-thumbnail">دریافت تصویر بندانگشتی PNG</button><button class="button secondary" data-action="video-voice-preview">پیش‌نمایش گویندگی انگلیسی</button></div><div class="form-fields section-gap"><p class="muted">پس از ساخت، ابتدا پیش‌نمایش را ببین. بارگذاری و انتشار فقط با زدن دکمه جداگانه و تأیید نهایی انجام می‌شود.</p><div class="field"><label><input id="autopilot-public" type="checkbox"> اجازه انتشار عمومی خودکار پس از ساخت را می‌دهم.</label><small>اگر فعال نشود، ویدئو خصوصی بارگذاری می‌شود. انتشار زمان‌بندی‌شده نیز با وضعیت خصوصی و زمان تعیین‌شده ثبت می‌شود.</small></div><div class="field"><label for="autopilot-publish-at">زمان انتشار عمومی (اختیاری)</label><input id="autopilot-publish-at" type="datetime-local"><small>زمان باید حداقل ۱۵ دقیقه در آینده باشد. در صورت تعیین زمان، تیک انتشار فوری عمومی را فعال نکن.</small></div></div><p class="muted">موتور Nexora AI ویدئوی انگلیسی ۸ تا ۱۲ دقیقه‌ای با صحنه‌های تصویری، گویندگی انگلیسی اختصاصی و زیرنویس انگلیسی روی تصویر می‌سازد؛ فایل SRT جداگانه نیز قابل دریافت است. برای گویندگی، کلید ElevenLabs و شناسه صدای انگلیسی باید در تنظیمات امن ثبت شوند. اجرای تولید در مرورگر نیازمند بازماندن صفحه تا پایان کار است.</p><div id="video-studio-result" class="section-gap"><p class="muted">هنوز ویدئویی ساخته نشده است.</p></div></section>'}
function renderYoutubeComments(){const box=$("#youtube-comments-list");if(!box)return;if(!youtubeComments.length){box.innerHTML="<p class=muted>کامنتی برای نمایش دریافت نشد.</p>";return}box.innerHTML=youtubeComments.map((item,i)=>"<article class=list-card><div><h3>"+esc(item.author)+"</h3><p>"+esc(item.text)+"</p><small class=muted>"+(item.publishedAt?new Date(item.publishedAt).toLocaleString("fa-IR"):"")+" · "+Number(item.replyCount||0).toLocaleString("fa-IR")+" پاسخ</small><p><a href="+esc(item.videoUrl)+" target=_blank rel=noopener>مشاهده ویدئو</a></p></div>"+(item.replied?"<p class=muted>پاسخ ارسال شد</p>":item.canReply===false?"<p class=muted>امکان پاسخ به این گفتگو در یوتیوب غیرفعال است.</p>":"<div class=field><textarea id=\"comment-reply-"+i+"\" rows=3 maxlength=10000 placeholder=\"پاسخ خودت را بنویس یا پاسخ پیشنهادی بساز\">"+esc(item.draft||"")+"</textarea><div class=actions><button class=\"button secondary\" data-action=comment-draft data-index=\""+i+"\">ساخت پاسخ هوشمند</button><button class=\"button primary\" data-action=comment-reply data-index=\""+i+"\">بازبینی و ارسال پاسخ</button></div></div>")+"</article>").join("")}
function settings(){return heading("فضای کاری","تنظیمات و داده‌ها","اطلاعات محلی در همین مرورگر نگهداری می‌شوند؛ اطلاعات کانال و توکن‌ها از Worker دریافت می‌شوند.", "")+'<div class="two-col"><section class="panel"><div class="panel-head"><h2>تنظیمات فضای کاری</h2></div><form id="settings-form" class="form-fields"><div class="field"><label for="workspace-name">نام فضای کاری</label><input id="workspace-name" name="workspaceName" value="'+esc(state.settings?.workspaceName||"AI Business Core")+'" maxlength="80" required></div><button class="button primary" type="submit">ذخیره تنظیمات</button></form></section><section class="panel"><div class="panel-head"><h2>مدیریت داده‌ها</h2></div><p class="muted">پیش از پاک‌کردن داده‌های مرورگر یا جابه‌جایی دستگاه، نسخه پشتیبان بگیرید.</p><div class="actions">'+btn("خروجی پشتیبان","export-data",false)+btn("بازیابی پشتیبان","import-data",false)+'<input type="file" id="import-file" accept="application/json,.json" hidden></div><hr class="soft-line"><button class="button danger" data-action="clear-data">پاک‌کردن همه داده‌های محلی</button></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>همگام‌سازی ابری با D1</h2><p>برای همگام‌سازی خودکار، می‌توانی ذخیره توکن روی همین دستگاه را فعال کنی. این گزینه روی دستگاه مشترک توصیه نمی‌شود؛ توکن در حافظه مرورگر قابل دسترسی است.</p></div><span class="pill">Cloudflare D1</span></div><div class="form-fields"><div class="field"><label for="cloud-workspace">شناسه فضای کاری</label><input id="cloud-workspace" value="default" maxlength="64" dir="ltr"></div><div class="field"><label for="cloud-token">توکن دسترسی برنامه (APP_ACCESS_TOKEN)</label><input id="cloud-token" type="password" autocomplete="off" placeholder="توکن Worker را وارد کن" dir="ltr"></div><div class="field"><label><input id="remember-cloud-token" type="checkbox" '+(localStorage.getItem(CLOUD_TOKEN_KEY)?"checked":"")+'> روی این دستگاه به خاطر بسپار و همگام‌سازی خودکار را فعال کن</label></div><div class="actions"><button class="button primary" data-action="cloud-connect">بررسی اتصال</button><button class="button secondary" data-action="cloud-pull">دریافت از ابر</button><button class="button secondary" data-action="cloud-push">ارسال به ابر</button></div><p class="muted">دریافت از ابر، داده‌های محلی فعلی را جایگزین می‌کند؛ قبلش نسخه پشتیبان بگیر.</p></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>مدیریت کانال یوتیوب</h2><p>اطلاعات کانال، ویدئوهای اخیر، آمار عملکرد و بارگذاری ویدئو از طریق اتصال امن Worker.</p></div><span class="pill">YouTube API</span></div><div class="actions"><button class="button primary" data-action="youtube-connect">اتصال مجدد / اعطای مجوز آمار</button><button class="button secondary" data-action="youtube-refresh">دریافت اطلاعات کانال</button><button class="button secondary" data-action="youtube-analytics">دریافت آمار و درآمد ۳۰ روز اخیر</button></div><div id="youtube-account-status" class="muted" style="margin-top:12px">برای شروع، توکن Worker را در بخش همگام‌سازی ابری وارد کن.</div><div id="youtube-dashboard" class="section-gap"></div><div class="panel section-gap" id="youtube-monetization"><h3>💰 درآمد و وضعیت درآمدزایی یوتیوب</h3><p class="muted">برای دریافت درآمد تخمینی و نمایش وضعیت قابل‌دسترسی از YouTube Analytics، آمار را دریافت کن. شرایط رسمی عضویت و تأیید نهایی فقط در YouTube Studio مشخص می‌شود.</p><div id="youtube-monetization-data" class="muted">هنوز داده‌ای دریافت نشده است.</div><p><a href="https://studio.youtube.com/" target="_blank" rel="noopener">بررسی Monetization در YouTube Studio</a></p></div><hr class="soft-line"><div class="panel-head"><div><h3>💬 صندوق پیام‌ها و کامنت‌های یوتیوب</h3><p>کامنت‌ها را دریافت کن، پاسخ پیشنهادی هوش مصنوعی بساز و فقط پس از بازبینی خودت ارسال کن.</p></div><button class="button secondary" data-action="youtube-comments">دریافت کامنت‌ها</button></div><div id="youtube-comments-list" class="section-gap"><p class="muted">برای دریافت آخرین کامنت‌ها، دکمه بالا را بزن.</p></div><hr class="soft-line"><h3>بارگذاری ویدئو</h3><form id="youtube-upload-form" class="form-fields"><div class="field"><label for="yt-video-title">عنوان ویدئو</label><input id="yt-video-title" name="title" maxlength="100" required></div><div class="field"><label for="yt-video-description">توضیحات</label><textarea id="yt-video-description" name="description" rows="4" maxlength="5000"></textarea></div><div class="field"><label for="yt-video-tags">برچسب‌ها (با کاما جدا کن)</label><input id="yt-video-tags" name="tags" placeholder="هوش مصنوعی, آموزش"></div><div class="field"><label for="yt-video-privacy">وضعیت انتشار</label><select id="yt-video-privacy" name="privacyStatus"><option value="private">خصوصی (پیشنهادی برای تست)</option><option value="unlisted">فهرست‌نشده</option><option value="public">عمومی</option></select></div><div class="field"><label><input id="yt-confirm-public" type="checkbox"> انتشار عمومی این ویدئو را صریحاً تأیید می‌کنم.</label></div><div class="field"><label for="yt-video-publish-at">زمان انتشار زمان‌بندی‌شده (اختیاری)</label><input id="yt-video-publish-at" name="publishAt" type="datetime-local"><small>اگر زمان انتخاب کنی، ویدئو به‌صورت خصوصی بارگذاری و در زمان تعیین‌شده منتشر می‌شود؛ حداقل ۱۵ دقیقه بعد از زمان فعلی.</small></div><div class="field"><label for="yt-video-file">فایل ویدئو (حداکثر ۶۴ مگابایت)</label><input id="yt-video-file" name="video" type="file" accept="video/*" required></div><button class="button primary" type="submit" id="youtube-upload-button">بارگذاری در یوتیوب</button><p class="muted">آپلود واقعی است. برای تست، حالت خصوصی را انتخاب کن. پروژه‌های API تأییدنشده ممکن است ویدئوها را فقط خصوصی منتشر کنند.</p></form><div id="youtube-upload-result" class="muted"></div></section><section class="panel section-gap"><h2>پیش‌نیازهای گوگل</h2><ul class="boundary-list"><li>YouTube Data API v3 و YouTube Analytics API باید در Google Cloud فعال باشند.</li><li>برای دریافت آمار کامل، پس از تغییر مجوزها یک بار اتصال مجدد لازم است.</li><li>توکن‌های OAuth فقط به‌صورت رمزگذاری‌شده در D1 ذخیره می‌شوند؛ فایل ویدئو از مرورگر به Worker و سپس YouTube منتقل می‌شود.</li></ul></section>'}
